#include <bits/stdc++.h>
using namespace std;

void get_input(int &x) {
    x = 0; bool neg = false; char c;
    do {
        c = getchar();
        if (c == '-') neg = true;
    } while (!isdigit(c));
    while (isdigit(c)) {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

void get_input_ll(long long &x) {
    x = 0; bool neg = false; char c;
    do {
        c = getchar();
        if (c == '-') neg = true;
    } while (!isdigit(c));
    while (isdigit(c)) {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

long long n, k, mod;
int factorials[262155], invFactorials[262155], logs[262155], cnt2[262155];
int dp[262155][31];
bool visited[262155][31];
vector<pair<int, int>> trace;

int countDiv2(int x) {
    int cnt = 0;
    while (x && (x & 1) == 0) {
        ++cnt; x >>= 1;
    }
    return cnt;
}

int fast_pow(int base, long long exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod; exp >>= 1;
    }
    return res;
}

int choose(int n, int m) {
    return (long long)factorials[n] * invFactorials[m] % mod * invFactorials[n - m] % mod;
}

int recurse(int n, int k) {
    if (n == 0) return 1;
    if (k == 0) return 0;
    if (dp[n][k] != -1) return dp[n][k];
    int res = 0;
    int limit = (1 << logs[n]);
    for (int i = n; i >= limit; i -= 2) {
        res = (res + (long long)choose(n, i) * recurse(n - i, k - 1) % mod * k) % mod;
    }
    return dp[n][k] = res;
}

int main() {
    get_input(n); get_input(k); get_input_ll(mod);
    factorials[0] = 1;
    memset(visited, 0, sizeof(visited));
    logs[0] = -1;
    for (int i = 1; i <= 262150; ++i) {
        factorials[i] = (long long)factorials[i - 1] * i % mod;
        logs[i] = logs[i >> 1] + 1;
        cnt2[i] = cnt2[i - 1] + countDiv2(i);
    }
    invFactorials[262150] = fast_pow(factorials[262150], mod - 2);
    for (int i = 262149; i > 0; --i)
        invFactorials[i] = (long long)invFactorials[i + 1] * (i + 1) % mod;
    invFactorials[0] = invFactorials[1];
    if (n & 1) {
        printf("%d\n", fast_pow(k, n));
    } else {
        int cnt = 0;
        for (int i = 0; i < 62; ++i) {
            if (n & (1LL << i)) ++cnt;
        }
        int ans = fast_pow(k, n);
        printf("%d\n", ((ans - recurse(n, k)) % mod + mod) % mod);
    }
}
